#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    reason = "tests and benches use unwrap and expect to keep fixture setup concise"
)]

//! `fallow fix` and generated files (issue #4912).
//!
//! A generator writes its output again on its next run, so the removal of an
//! unused export in that output does not last. The fixer keeps such a file
//! and reports it with `skip_reason: "generated_source"`.

use std::path::Path;

use crate::common::{parse_json, run_fallow_in_root};

const GENERATED: &str = "// Generated by graph-tool from messages.graphql. Do not edit.\n\
export const usedOperation = 1;\n\
export const unusedOperation = 2;\n\
export enum Kind {\n  Used = 'used',\n  Unused = 'unused',\n}\n";

const WRITTEN: &str = "export const usedHelper = 1;\nexport const unusedHelper = 2;\n";

fn write_project(root: &Path) {
    std::fs::write(
        root.join("package.json"),
        r#"{ "name": "generated-file", "version": "1.0.0", "type": "module", "main": "src/index.ts" }"#,
    )
    .unwrap();
    std::fs::create_dir_all(root.join("src")).unwrap();
    std::fs::write(root.join("src/messages.graphql.ts"), GENERATED).unwrap();
    std::fs::write(root.join("src/helpers.ts"), WRITTEN).unwrap();
    std::fs::write(
        root.join("src/index.ts"),
        "import { Kind, usedOperation } from './messages.graphql';\n\
         import { usedHelper } from './helpers';\n\
         console.log(usedOperation, usedHelper, Kind.Used);\n",
    )
    .unwrap();
}

#[test]
fn fix_keeps_a_generated_file_and_reports_the_skip() {
    // The project lives below a folder named `generated`. The path rule
    // reads only the path below the project root, so this folder name does
    // not make each file of the project a generated file.
    let dir = tempfile::tempdir().unwrap();
    let root = &dir.path().join("generated/app");
    std::fs::create_dir_all(root).unwrap();
    write_project(root);

    let output = run_fallow_in_root("fix", root, &["--yes", "--format", "json", "--quiet"]);
    assert_eq!(output.code, 0, "{}", output.stderr);
    let envelope = parse_json(&output);
    let fixes = envelope["fixes"].as_array().unwrap();

    let skipped: Vec<(&str, &str)> = fixes
        .iter()
        .filter(|fix| fix["skipped"] == true)
        .map(|fix| {
            (
                fix["path"].as_str().unwrap(),
                fix["skip_reason"].as_str().unwrap(),
            )
        })
        .collect();
    assert_eq!(
        skipped,
        [("src/messages.graphql.ts", "generated_source")],
        "the generated file is the only skipped file"
    );
    assert_eq!(
        envelope["skipped"], 0,
        "an intentional skip is not a reported failure"
    );

    assert_eq!(
        std::fs::read_to_string(root.join("src/messages.graphql.ts")).unwrap(),
        GENERATED,
        "the generated file must not change: not its unused export and not its unused enum member"
    );
    assert_eq!(
        std::fs::read_to_string(root.join("src/helpers.ts")).unwrap(),
        "export const usedHelper = 1;\nconst unusedHelper = 2;\n",
        "the fixer still removes the unused export of a file that a person wrote"
    );
}
